package cn.mop.api;
import cn.mop.domain.DomainException;
import cn.mop.domain.contact.CustomerContact.QuietWindow;
import cn.mop.domain.notification.OwnNotificationPreferenceDraft;
import cn.mop.domain.notification.OwnNotificationPreferenceDraft.LevelPreference;
import cn.mop.domain.notification.DeliveryReceiptState.Channel;
import cn.mop.domain.time.BusinessDates;
import org.junit.jupiter.api.Test;
import java.time.LocalTime;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class OwnNotificationPreferenceDraftTest {
    final UUID tenant=UUID.fromString("7a000000-0000-4000-8000-000000000001"),owner=UUID.fromString("7a000000-0000-4000-8000-000000000002");
    OwnNotificationPreferenceDraft draft(LevelPreference level,List<Channel> channels,QuietWindow quiet){return new OwnNotificationPreferenceDraft(tenant,owner,level,channels,quiet);}
    QuietWindow night(){return new QuietWindow(true,LocalTime.of(22,0),LocalTime.of(7,0));}
    @Test void unknownValuesStayNullWithoutDefaultLevelChannelsOrWindow(){var d=draft(null,null,null);assertNull(d.requestedLevel());assertNull(d.requestedChannels());assertNull(d.requestedQuietWindow());assertFalse(d.effective());assertEquals("CONFIG_PENDING",d.configurationStatus());}
    @Test void missingTenantOrOwnerCannotBeEncoded(){assertEquals(400,assertThrows(DomainException.class,()->new OwnNotificationPreferenceDraft(null,owner,null,null,null)).status);assertEquals(400,assertThrows(DomainException.class,()->new OwnNotificationPreferenceDraft(tenant,null,null,null,null)).status);}
    @Test void unknownChannelsAndExplicitNoRequestedChannelsAreDistinct(){var unknown=draft(null,null,null);var empty=draft(null,List.of(),null);assertNull(unknown.requestedChannels());assertEquals(List.of(),empty.requestedChannels());assertNotEquals(unknown.fingerprint(),empty.fingerprint());assertNull(empty.effectiveChannels());assertNull(empty.deliveryDecision());}
    @Test void requestedChannelsAreCanonicalSetOrderNotPriority(){var first=draft(LevelPreference.ALL,List.of(Channel.VOICE,Channel.EMAIL,Channel.WECHAT_WORK),null);var second=draft(LevelPreference.ALL,List.of(Channel.WECHAT_WORK,Channel.EMAIL,Channel.VOICE),null);assertEquals(List.of(Channel.EMAIL,Channel.VOICE,Channel.WECHAT_WORK),first.requestedChannels());assertEquals(first,second);assertArrayEquals(first.canonicalBytes(),second.canonicalBytes());}
    @Test void channelInputsAndResultsCannotBeMutatedByAlias(){var input=new ArrayList<>(List.of(Channel.SMS,Channel.EMAIL));var d=draft(null,input,null);input.clear();assertEquals(List.of(Channel.EMAIL,Channel.SMS),d.requestedChannels());assertThrows(UnsupportedOperationException.class,()->d.requestedChannels().clear());}
    @Test void duplicateChannelsAreRejectedNotSilentlyMerged(){assertEquals(400,assertThrows(DomainException.class,()->draft(null,List.of(Channel.SMS,Channel.SMS),null)).status);}
    @Test void nullChannelInsideAnExplicitListIsInvalid(){assertThrows(DomainException.class,()->draft(null,Arrays.asList(Channel.EMAIL,null),null));}
    @Test void allSixContractChannelNamesAreAcceptedWithoutActivation(){var d=draft(LevelPreference.ALL,Arrays.asList(Channel.values()),null);assertEquals(6,d.requestedChannels().size());assertFalse(d.effective());assertNull(d.effectiveChannels());assertFalse(d.notificationDispatched());}
    @Test void threeExplicitLevelPreferencesAreRetainedIndependently(){assertEquals(Set.of("P1_ONLY","P1_P2","ALL"),new HashSet<>(Arrays.stream(LevelPreference.values()).map(Enum::name).toList()));Set<String> hashes=new HashSet<>();for(var level:LevelPreference.values()){var d=draft(level,null,null);assertEquals(level,d.requestedLevel());hashes.add(d.fingerprint());}assertEquals(3,hashes.size());}
    @Test void crossMidnightMinuteWindowIsARequestNotAnAppliedPolicy(){var d=draft(LevelPreference.P1_P2,List.of(Channel.EMAIL),night());assertTrue(d.requestedQuietWindow().crossesMidnight());assertEquals(LocalTime.of(22,0),d.requestedQuietWindow().start());assertNull(d.effectiveQuietWindow());assertFalse(d.notificationDispatched());}
    @Test void explicitDisabledAndUnknownWindowRemainDifferent(){var unknown=draft(null,null,new QuietWindow(null,null,null));var disabled=draft(null,null,new QuietWindow(false,null,null));assertNull(unknown.requestedQuietWindow().enabled());assertEquals(false,disabled.requestedQuietWindow().enabled());assertNotEquals(unknown.fingerprint(),disabled.fingerprint());assertNotEquals(unknown.fingerprint(),draft(null,null,null).fingerprint());}
    @Test void disabledOrUnknownWindowsCannotCarryHiddenTimes(){for(Boolean enabled:Arrays.asList(null,false))assertThrows(DomainException.class,()->draft(null,null,new QuietWindow(enabled,LocalTime.MIDNIGHT,LocalTime.NOON)));}
    @Test void enabledWindowNeedsBothDifferentMinuteBoundaries(){for(LocalTime end:Arrays.asList(null,LocalTime.MIDNIGHT,LocalTime.of(1,0,1),LocalTime.of(1,0,0,1)))assertThrows(DomainException.class,()->draft(null,null,new QuietWindow(true,LocalTime.MIDNIGHT,end)));assertThrows(DomainException.class,()->draft(null,null,new QuietWindow(true,null,LocalTime.NOON)));}
    @Test void explicitMinuteParserRejectsInvalidFormats(){for(String value:Arrays.asList(null,"7:00","24:00","07:00:00","07:00\n"," 07:00"))assertThrows(DomainException.class,()->QuietWindow.parseMinute(value));assertEquals(LocalTime.of(7,0),QuietWindow.parseMinute("07:00"));}
    @Test void timezoneIsTheFixedBusinessZone(){var d=draft(null,null,night());assertEquals("Asia/Shanghai",d.timezone());assertEquals(BusinessDates.ZONE.getId(),d.requestedQuietWindow().zone());}
    @Test void noReceiverMappingOrSendPermissionIsInvented(){var d=draft(LevelPreference.P1_ONLY,List.of(Channel.VOICE),new QuietWindow(false,null,null));assertNull(d.verifiedReceiverId());assertEquals("NOT_VERIFIED",d.receiverBindingStatus());assertNull(d.deliveryDecision());assertNull(d.effectiveLevelPreference());assertNull(d.effectiveChannels());assertNull(d.effectiveQuietWindow());assertFalse(d.notificationDispatched());assertTrue(d.p1QuietBypassIsContractRule());assertEquals("OWN_NOTIFICATION_PREFERENCE_DRAFT",d.recordSource());}
    @Test void independentLengthPrefixedGoldenVectorMatches(){var d=draft(LevelPreference.P1_P2,List.of(Channel.VOICE,Channel.EMAIL),night());assertEquals(202,d.canonicalBytes().length);assertEquals("ecae66e7ed94c48a01fc19b2d53add2c683c66e4a5b0f84ca1720c2fca1942a5",d.fingerprint());}
    @Test void returnedBytesAreDetached(){var d=draft(LevelPreference.ALL,List.of(Channel.SMS),night());String hash=d.fingerprint();byte[] first=d.canonicalBytes();first[0]=99;assertEquals(hash,d.fingerprint());assertNotEquals(first[0],d.canonicalBytes()[0]);}
    @Test void tenantOwnerLevelChannelAndWindowChangesBindDifferentContent(){var d=draft(LevelPreference.P1_ONLY,List.of(Channel.EMAIL),night());Set<String> hashes=new HashSet<>(List.of(d.fingerprint(),new OwnNotificationPreferenceDraft(owner,tenant,d.requestedLevel(),d.requestedChannels(),night()).fingerprint(),draft(LevelPreference.P1_P2,d.requestedChannels(),night()).fingerprint(),draft(d.requestedLevel(),List.of(Channel.SMS),night()).fingerprint(),draft(d.requestedLevel(),d.requestedChannels(),new QuietWindow(true,LocalTime.of(21,0),LocalTime.of(7,0))).fingerprint()));assertEquals(5,hashes.size());}
}
